#include <stdbool.h>
#include <stdint.h>

#define DISCHARGE_OC_LIMIT_MA 18000
#define DISCHARGE_OC_CONFIRM_SAMPLES 4u

typedef struct {
    int32_t pack_current_ma;
    uint8_t discharge_oc_samples;
    bool discharge_oc_fault;
    bool discharge_fet_cmd;
    bool fault_event_pending;
} Bms;

static void bms_check_discharge_overcurrent(Bms *b)
{
    if (b->pack_current_ma > DISCHARGE_OC_LIMIT_MA) {
        if (b->discharge_oc_samples < DISCHARGE_OC_CONFIRM_SAMPLES) {
            ++b->discharge_oc_samples;
        }
    } else {
        b->discharge_oc_samples = 0u;
    }

    if (b->discharge_oc_samples >= DISCHARGE_OC_CONFIRM_SAMPLES) {
        b->discharge_oc_fault = true;
        b->discharge_fet_cmd = false;
        b->fault_event_pending = true;
    }
}

void bms_fast_protection_task(Bms *b)
{
    bms_check_discharge_overcurrent(b);
}
